import { z } from "zod";
import { DEFAULT_THEME, THEME_IDS } from "../../../lib/experience/themes";
import { CURVES, TIERS } from "./difficulty";
import { GateSchema } from "./gates";

/**
 * Blueprint v2 — the complete, declarative definition of a DOSSIER event.
 * Authored in Studio, generated by the compiler, or loaded from a pack
 * (`packs/<slug>/dossier.yaml`). Validated structurally here; semantically
 * (reachability, facts, leakage…) by `compiler/validate.ts`.
 */

export const Id = z.string().regex(/^[a-z0-9][a-z0-9-]{0,62}$/, "ids are lowercase letters, digits and dashes (max 63), starting with a letter or digit");
const Md = z.string().max(20_000);
const Short = (n: number) => z.string().max(n);

export const FAMILIES = ["cryptic", "browser", "forensics", "ctf", "osint", "inquest", "physical", "final", "custom"] as const;
export const Family = z.enum(FAMILIES);
export type FamilyId = (typeof FAMILIES)[number];

export const HINT_LEVELS = ["nudge", "partial", "artifact", "technique", "partial-answer", "explicit"] as const;
export type HintLevel = (typeof HINT_LEVELS)[number];

const Iso = z.string().refine((s) => !Number.isNaN(Date.parse(s)), "not a valid ISO-8601 timestamp");

/* ─────────────────────────── World facts ─────────────────────────── */

export const FactSpec = z.discriminatedUnion("gen", [
  z.object({ gen: z.literal("const"), value: z.string().max(400), secret: z.boolean().default(false), description: Short(200).default("") }).strict(),
  z.object({ gen: z.literal("word"), from: z.array(z.string().min(1).max(40)).min(2).max(400), secret: z.boolean().default(true), description: Short(200).default("") }).strict(),
  z.object({ gen: z.literal("code"), pattern: z.string().min(1).max(60), secret: z.boolean().default(true), description: Short(200).default("") }).strict(),
  z.object({ gen: z.literal("int"), min: z.number().int(), max: z.number().int(), secret: z.boolean().default(true), description: Short(200).default("") }).strict(),
  z.object({ gen: z.literal("hex"), bytes: z.number().int().min(1).max(32), secret: z.boolean().default(true), description: Short(200).default("") }).strict(),
  z.object({ gen: z.literal("ipv4"), cidr: z.string().regex(/^\d+\.\d+\.\d+\.\d+\/\d+$/), secret: z.boolean().default(false), description: Short(200).default("") }).strict(),
  z
    .object({
      gen: z.literal("time"),
      base: z.string().regex(/^\d{2}:\d{2}$/),
      jitterMinutes: z.number().int().min(0).max(720).default(0),
      secret: z.boolean().default(true),
      description: Short(200).default(""),
    })
    .strict(),
  z.object({ gen: z.literal("pick"), options: z.array(z.string().min(1).max(200)).min(1).max(100), secret: z.boolean().default(false), description: Short(200).default("") }).strict(),
  z.object({ gen: z.literal("derive"), template: z.string().min(1).max(400), secret: z.boolean().default(true), description: Short(200).default("") }).strict(),
]);
export type FactSpec = z.infer<typeof FactSpec>;

/* ─────────────────────────── Story model ─────────────────────────── */

export const Character = z
  .object({
    id: Id,
    name: z.string().min(1).max(80),
    role: Short(120).default(""),
    bio: Md.default(""),
    suspect: z.boolean().default(false),
    traits: z.array(Short(40)).max(12).default([]),
    relationships: z.array(z.object({ to: Id, kind: Short(60) }).strict()).max(20).default([]),
  })
  .strict();

export const Location = z
  .object({
    id: Id,
    name: z.string().min(1).max(80),
    description: Md.default(""),
    geo: z.object({ lat: z.number().min(-90).max(90), lon: z.number().min(-180).max(180) }).strict().optional(),
  })
  .strict();

export const StoryArtifact = z
  .object({ id: Id, name: z.string().min(1).max(100), kind: Short(40).default("object"), description: Md.default("") })
  .strict();

export const TimelineEntry = z
  .object({
    id: Id,
    at: z.string().min(1).max(40),
    title: z.string().min(1).max(140),
    body: Md.default(""),
    actors: z.array(Id).default([]),
    location: Id.optional(),
    public: z.boolean().default(false),
    /** Revealed to a team once it holds this evidence. */
    requiresEvidence: Id.optional(),
  })
  .strict();

export const Story = z
  .object({
    title: z.string().min(1).max(120),
    codename: Short(40).default(""),
    premise: Md.default(""),
    briefing: Md.default(""),
    characters: z.array(Character).max(60).default([]),
    organizations: z.array(z.object({ id: Id, name: z.string().min(1).max(100), description: Md.default("") }).strict()).max(30).default([]),
    locations: z.array(Location).max(60).default([]),
    artifacts: z.array(StoryArtifact).max(80).default([]),
    timeline: z.array(TimelineEntry).max(120).default([]),
    motives: z.array(z.object({ character: Id, text: Short(400) }).strict()).max(40).default([]),
    truth: z
      .object({
        culprit: Id.optional(),
        motive: Short(400).default(""),
        method: Short(400).default(""),
        location: Id.optional(),
        time: Short(40).default(""),
        keyEvidence: z.array(Id).default([]),
        /** Shown to teams after the event ends. */
        explanation: Md.default(""),
      })
      .strict()
      .default({ motive: "", method: "", time: "", keyEvidence: [], explanation: "" }),
  })
  .strict();
export type StoryModel = z.infer<typeof Story>;

/* ─────────────────────────── Structure ─────────────────────────── */

export const Act = z.object({ id: Id, title: z.string().min(1).max(100), summary: Md.default(""), phase: Id.optional() }).strict();

export const Round = z
  .object({
    id: Id,
    act: Id,
    title: z.string().min(1).max(100),
    family: Family,
    tier: z.enum(TIERS).default("intermediate"),
    intro: Md.default(""),
  })
  .strict();

export const Hint = z
  .object({
    level: z.enum(HINT_LEVELS).default("nudge"),
    cost: z.number().int().min(0).max(10_000).optional(),
    text: Md.min(1),
  })
  .strict();
export type HintDef = z.infer<typeof Hint>;

export const Rewards = z
  .object({
    evidence: z.array(Id).default([]),
    flags: z.record(z.string().max(60), z.union([z.boolean(), z.number(), z.string().max(200)])).default({}),
    resources: z.object({ intel: z.number().int().optional(), tokens: z.number().int().optional(), hints: z.number().int().optional() }).strict().default({}),
    phase: Id.optional(),
    timeline: z.array(Id).default([]),
    locations: z.array(Id).default([]),
  })
  .strict()
  .default({ evidence: [], flags: {}, resources: {}, timeline: [], locations: [] });

export const Node = z
  .object({
    id: Id,
    round: Id,
    title: z.string().min(1).max(120),
    primitive: z.string().min(1).max(60),
    briefing: Md.default(""),
    config: z.record(z.string(), z.unknown()).default({}),
    gate: GateSchema.optional(),
    scoring: z
      .object({
        points: z.number().int().min(0).max(100_000).default(100),
        firstBloodBonus: z.number().int().min(0).max(10_000).default(0),
        dynamic: z.object({ minimum: z.number().int().min(0), decay: z.number().int().min(1).max(10_000) }).strict().optional(),
      })
      .strict()
      .default({ points: 100, firstBloodBonus: 0 }),
    hints: z.array(Hint).max(8).default([]),
    rewards: Rewards,
    /** Aliases exported to the world: `{ maintPass: "answer" }` makes `{{maintPass}}` = this node's `answer` output. */
    exports: z.record(z.string().regex(/^[A-Za-z][A-Za-z0-9_]*$/), z.string().max(60)).default({}),
    optional: z.boolean().default(false),
    redHerring: Id.optional(),
    estimatedMinutes: z.number().int().min(1).max(600).default(15),
    maxAttempts: z.number().int().min(1).max(1000).optional(),
    skills: z.array(Short(40)).max(12).default([]),
    tools: z.array(Short(40)).max(12).default([]),
    tags: z.array(Short(30)).max(10).default([]),
    position: z.object({ x: z.number().min(0).max(100), y: z.number().min(0).max(100) }).strict().optional(),
    /** Informational: family label for scoring breakdown / legacy boards (defaults to the round family). */
    family: z.string().max(30).optional(),
    category: z.string().max(40).optional(),
  })
  .strict();
export type NodeDef = z.infer<typeof Node>;

export const EVIDENCE_KINDS = ["document", "photo", "testimony", "object", "record", "audio", "log", "capture", "repository", "database", "message", "location"] as const;

export const Evidence = z
  .object({
    id: Id,
    title: z.string().min(1).max(120),
    kind: z.enum(EVIDENCE_KINDS).default("document"),
    summary: Short(300).default(""),
    body: Md.default(""),
    about: z
      .object({ characters: z.array(Id).default([]), locations: z.array(Id).default([]), timeline: z.array(Id).default([]) })
      .strict()
      .default({ characters: [], locations: [], timeline: [] }),
    /** Auto-granted when this gate becomes true (e.g. `{always: true}` for starting evidence). */
    gate: GateSchema.optional(),
    image: z.string().regex(/^assets\/[A-Za-z0-9._\-/]+$/).optional(),
  })
  .strict();
export type EvidenceDef = z.infer<typeof Evidence>;

export const SiteDef = z
  .object({
    id: Id,
    template: z.enum(["intranet", "social", "news", "forum"]).default("intranet"),
    title: z.string().min(1).max(80),
    org: z.string().max(100).default(""),
    tagline: Short(160).default(""),
    accent: z.string().regex(/^#[0-9a-fA-F]{6}$/).default("#1f5fbf"),
    pages: z.array(z.object({ path: z.string().regex(/^[a-z0-9][a-z0-9-/]{0,60}$/), title: z.string().min(1).max(80), body: Md.default(""), nav: z.boolean().default(true) }).strict()).max(20).default([]),
    news: z.array(z.object({ title: z.string().max(120), date: Short(40), body: Short(600) }).strict()).max(12).default([]),
    people: z.array(z.object({ name: z.string().max(80), title: Short(80), email: Short(120).default(""), ext: Short(20).default("") }).strict()).max(40).default([]),
  })
  .strict();
export type SiteDefT = z.infer<typeof SiteDef>;

export const Checkpoint = z
  .object({
    id: Id,
    name: z.string().min(1).max(80),
    kind: z.enum(["qr", "gps"]).default("qr"),
    location: Short(160).default(""),
    instructions: Md.default(""),
    points: z.number().int().min(0).max(100_000).default(50),
    requiresApproval: z.boolean().default(true),
    pin: z.string().regex(/^\d{4,8}$/).optional(),
    geo: z.object({ lat: z.number().min(-90).max(90), lon: z.number().min(-180).max(180), radiusM: z.number().min(5).max(2000).default(40) }).strict().optional(),
    /** Only the first N teams may claim (0 = unlimited). */
    claimLimit: z.number().int().min(0).max(10_000).default(0),
    expiresAt: Iso.optional(),
    /** Printed codes are per team; a team can only claim its own code. */
    teamScoped: z.boolean().default(false),
  })
  .strict();
export type CheckpointDefV2 = z.infer<typeof Checkpoint>;

export const RELATION_KINDS = ["implicates", "alibi-for", "places-at", "contradicts", "supports", "owned-by", "sent-to", "motive-for", "precedes", "same-as"] as const;

export const Relation = z
  .object({
    from: z.string().regex(/^(ev|sus|loc|tl):[a-z0-9-]+$/),
    to: z.string().regex(/^(ev|sus|loc|tl):[a-z0-9-]+$/),
    kind: z.enum(RELATION_KINDS),
    note: Short(200).default(""),
  })
  .strict();

export const RedHerring = z
  .object({
    id: Id,
    description: Short(400),
    plausibility: z.number().min(0).max(1).default(0.6),
    /** Evidence ids that falsify this herring. */
    disprovedBy: z.array(Id).min(1),
    /** Evidence/nodes that make it look plausible. */
    supportedBy: z.array(Id).default([]),
  })
  .strict();

/**
 * How the event *presents itself*. Pure presentation: nothing here can change a
 * rule, an answer or a gate. `theme` picks one of the registered themes
 * (typography, surfaces, navigation, universe, opening sequence, sound);
 * `cinematic` lets the organiser word the opening of the case.
 */
export const Presentation = z
  .object({
    theme: z.enum(THEME_IDS).default(DEFAULT_THEME),
    /** calm = short, quiet openings and little camera motion; cinematic = the full show. */
    intensity: z.enum(["calm", "balanced", "cinematic"]).default("balanced"),
    cinematic: z
      .object({
        /** "CASE 017". Derived from the event id when empty. */
        caseNumber: Short(24).default(""),
        /** The line under the title, e.g. "A radio club heard something at 03:14." */
        kicker: Short(120).default(""),
        /** Extra boot-log lines (after the system lines the engine derives from real state). */
        lines: z.array(Short(90)).max(8).default([]),
      })
      .strict()
      .default({ caseNumber: "", kicker: "", lines: [] }),
  })
  .strict()
  .default({ theme: DEFAULT_THEME, intensity: "balanced", cinematic: { caseNumber: "", kicker: "", lines: [] } });
export type PresentationT = z.infer<typeof Presentation>;

export const EventMeta = z
  .object({
    id: Id,
    title: z.string().min(1).max(100),
    tagline: Short(160).default(""),
    university: Short(120).default(""),
    organizer: Short(120).default(""),
    description: Md.default(""),
    codename: Short(40).default(""),
    logo: z.string().regex(/^assets\/[A-Za-z0-9._\-/]+$/).optional(),
    theme: z.object({ accent: z.enum(["green", "cyan", "magenta", "amber"]).default("green"), secondary: z.enum(["green", "cyan", "magenta", "amber"]).default("cyan") }).strict().default({ accent: "green", secondary: "cyan" }),
    presentation: Presentation,
    mode: z.enum(["online", "hybrid", "onsite"]).default("hybrid"),
    durationMinutes: z.number().int().min(15).max(7 * 24 * 60).default(300),
    teamSize: z.object({ min: z.number().int().min(1).max(12).default(1), max: z.number().int().min(1).max(12).default(4) }).strict().default({ min: 1, max: 4 }),
    startsAt: Iso.optional(),
    endsAt: Iso.optional(),
    freezeAt: Iso.optional(),
    timezone: Short(60).default("UTC"),
    registration: z.object({ open: z.boolean().default(true), code: z.string().min(4).max(64).optional() }).strict().default({ open: true }),
    rules: Md.default(""),
    stuckAfterMinutes: z.number().int().min(5).max(600).default(30),
    bootLines: z.array(Short(80)).max(8).default([]),
  })
  .strict();

export const Blueprint = z
  .object({
    schema: z.literal("dossier/v2").default("dossier/v2"),
    event: EventMeta,
    story: Story,
    world: z.object({ facts: z.record(z.string().regex(/^[A-Za-z][A-Za-z0-9_]*$/), FactSpec).default({}) }).strict().default({ facts: {} }),
    acts: z.array(Act).min(1).max(12),
    rounds: z.array(Round).min(1).max(30),
    nodes: z.array(Node).min(1).max(120),
    evidence: z.array(Evidence).max(200).default([]),
    sites: z.array(SiteDef).max(10).default([]),
    checkpoints: z.array(Checkpoint).max(60).default([]),
    relations: z.array(Relation).max(200).default([]),
    redHerrings: z.array(RedHerring).max(40).default([]),
    hintEconomy: z
      .object({
        currency: z.enum(["points", "tokens"]).default("points"),
        startingTokens: z.number().int().min(0).max(1000).default(0),
        costs: z
          .object({
            nudge: z.number().int().min(0).default(25),
            partial: z.number().int().min(0).default(50),
            artifact: z.number().int().min(0).default(60),
            technique: z.number().int().min(0).default(75),
            "partial-answer": z.number().int().min(0).default(100),
            explicit: z.number().int().min(0).default(200),
          })
          .strict()
          .default({ nudge: 25, partial: 50, artifact: 60, technique: 75, "partial-answer": 100, explicit: 200 }),
      })
      .strict()
      .default({ currency: "points", startingTokens: 0, costs: { nudge: 25, partial: 50, artifact: 60, technique: 75, "partial-answer": 100, explicit: 200 } }),
    difficulty: z.object({ curve: z.enum(CURVES).default("standard"), custom: z.array(z.enum(TIERS)).optional() }).strict().default({ curve: "standard" }),
    /** Standalone field checkpoints award points on their own (legacy "live" mode). */
    standaloneCheckpoints: z.boolean().default(false),
  })
  .strict();

export type BlueprintT = z.infer<typeof Blueprint>;
export type BlueprintInput = z.input<typeof Blueprint>;

export function hintCost(bp: BlueprintT, h: HintDef): number {
  return h.cost ?? bp.hintEconomy.costs[h.level];
}

export function familyOf(bp: BlueprintT, node: NodeDef): string {
  return node.family ?? bp.rounds.find((r) => r.id === node.round)?.family ?? "custom";
}
